Problem Description:
Build a 64-bit arithmetic shift register, with synchronous load. The shifter can shift both left and right, and by 1 or 8 bit positions, selected by "amount." Assume the right shit is an arithmetic right shift. 

// Signals are defined as below:
// (1) load: Loads shift register with data[63:0] instead of shifting. Active high.
// (2) ena: Chooses whether to shift. Active high. 
// (3) amount: Chooses which direction and how much to shift. 
//     (a) 2'b00: shift left by 1 bit. 
//     (b) 2'b01: shift left by 8 bits. 
//     (c) 2'b10: shift right by 1 bit. 
//     (d) 2'b11: shift right by 8 bits. 
// (4) q: The contents of the shifter.

module top_module(
	input clk,
	input load,
	input ena,
	input [1:0] amount,
	input [63:0] data,
	output reg [63:0] q);

Erroneous Implementation:

always @(posedge clk) begin
if (load) begin
if (ena) begin
case (amount)
2'b00: begin
q = {q[62:0], 1'b0};
end
2'b01: begin
q = {q[55:0], 8'b0};
end
2'b10: begin
q = {q[63], q[63:1]};
end
2'b11: begin
q = {8{q[63]}, q[63:8]};
end
default: begin
q = 64'hx;
end
endcase
end
end
end
endmodule

Feedback:
shift18.sv:221: syntax error
shift18.sv:221: error: Syntax error between internal '}' and closing '}' of repeat concatenation.

```verilog
module top_module(
    input clk,
    input load,
    input ena,
    input [1:0] amount,
    input [63:0] data,
    output reg [63:0] q
);

    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else if (ena) begin
            case (amount)
                2'b00: q <= {q[62:0], 1'b0};
                2'b01: q <= {q[55:0], 8'b0};
                2'b10: q <= {q[63], q[63:1]};
                2'b11: q <= {{8{q[63]}}, q[63:8]};
                default: q <= q;
            endcase
        end
    end

endmodule
```
